-- Stub of the live food_stores / food_orders / food_order_events shapes
-- (information_schema + check constraints from the 2026-10-26 read-only dump).
-- Test fixture only; no data.
create sequence public.food_order_number_seq;
create function public.food_next_order_number() returns text language sql as $$ select 'Z' || lpad(nextval('public.food_order_number_seq')::text, 6, '0') $$;
create table public.food_stores(
  id uuid default gen_random_uuid() not null,
  slug text default 'main'::text not null,
  name text not null,
  description text,
  phone text,
  address text,
  logo_path text,
  cover_path text,
  business_hours text,
  delivery_area text,
  delivery_fee numeric default 0 not null,
  minimum_order numeric default 0 not null,
  promptpay_name text,
  promptpay_id text,
  bank_name text,
  bank_account_name text,
  bank_account_number text,
  payment_qr_path text,
  is_open boolean default false not null,
  is_published boolean default false not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  merchant_account_id uuid,
  latitude double precision,
  longitude double precision,
  delivery_radius_km numeric default 5 not null,
  delivery_base_km numeric default 2 not null,
  delivery_fee_per_km numeric default 0 not null,
  admin_suspended_at timestamp with time zone,
  admin_suspended_reason text,
  admin_suspended_by uuid,
  pickup_latitude double precision,
  pickup_longitude double precision,
  pickup_note text,
  business_schedule jsonb default '{}'::jsonb not null,
  special_closed_dates date[] default '{}'::date[] not null,
  temporary_closed_until timestamp with time zone,
  temporary_closed_reason text,
  prep_time_min_minutes integer default 15 not null,
  prep_time_max_minutes integer default 30 not null,
  menu_category_order jsonb default '[]'::jsonb not null,
  share_code text not null,
  scheduled_orders_enabled boolean default false not null,
  scheduled_min_notice_minutes integer default 30 not null,
  scheduled_max_days integer default 7 not null,
  tax_invoice_enabled boolean default false not null,
  tax_legal_name text,
  tax_id text,
  tax_branch text,
  tax_address text,
  stripe_payments_enabled boolean default false not null,
  constraint food_stores_address_length CHECK (((address IS NULL) OR (char_length(address) <= 500))),
  constraint food_stores_admin_suspension_reason CHECK (((admin_suspended_reason IS NULL) OR (char_length(admin_suspended_reason) <= 500))),
  constraint food_stores_business_schedule_object CHECK ((jsonb_typeof(business_schedule) = 'object'::text)),
  constraint food_stores_delivery_fee_check CHECK ((delivery_fee >= (0)::numeric)),
  constraint food_stores_delivery_zone_range CHECK (((delivery_radius_km > (0)::numeric) AND (delivery_radius_km <= (50)::numeric) AND (delivery_base_km >= (0)::numeric) AND (delivery_base_km <= (50)::numeric) AND (delivery_fee_per_km >= (0)::numeric) AND (delivery_fee_per_km <= (1000)::numeric))),
  constraint food_stores_description_length CHECK (((description IS NULL) OR (char_length(description) <= 1000))),
  constraint food_stores_location_pair CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR ((latitude IS NOT NULL) AND (longitude IS NOT NULL) AND ((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision)) AND ((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))))),
  constraint food_stores_menu_category_order_array CHECK ((jsonb_typeof(menu_category_order) = 'array'::text)),
  constraint food_stores_minimum_order_check CHECK ((minimum_order >= (0)::numeric)),
  constraint food_stores_name_length CHECK (((char_length(name) >= 1) AND (char_length(name) <= 100))),
  constraint food_stores_phone_length CHECK (((phone IS NULL) OR (char_length(phone) <= 50))),
  constraint food_stores_pickup_note_length CHECK (((pickup_note IS NULL) OR (char_length(pickup_note) <= 500))),
  constraint food_stores_pickup_pair CHECK ((((pickup_latitude IS NULL) AND (pickup_longitude IS NULL)) OR (((pickup_latitude >= ('-90'::integer)::double precision) AND (pickup_latitude <= (90)::double precision)) AND ((pickup_longitude >= ('-180'::integer)::double precision) AND (pickup_longitude <= (180)::double precision))))),
  constraint food_stores_pkey PRIMARY KEY (id),
  constraint food_stores_prep_time_range CHECK ((((prep_time_min_minutes >= 1) AND (prep_time_min_minutes <= 240)) AND ((prep_time_max_minutes >= prep_time_min_minutes) AND (prep_time_max_minutes <= 240)))),
  constraint food_stores_promptpay_id_format_check CHECK (((promptpay_id IS NULL) OR (btrim(promptpay_id) = ''::text) OR ((length(regexp_replace(promptpay_id, '[^0-9]'::text, ''::text, 'g'::text)) = ANY (ARRAY[10, 13, 15])) AND ((length(regexp_replace(promptpay_id, '[^0-9]'::text, ''::text, 'g'::text)) <> 10) OR (regexp_replace(promptpay_id, '[^0-9]'::text, ''::text, 'g'::text) ~~ '0%'::text))))),
  constraint food_stores_scheduled_max_days_check CHECK (((scheduled_max_days >= 1) AND (scheduled_max_days <= 30))),
  constraint food_stores_scheduled_notice_check CHECK (((scheduled_min_notice_minutes >= 15) AND (scheduled_min_notice_minutes <= 1440))),
  constraint food_stores_share_code_format CHECK ((share_code ~ '^[a-hjkmnp-z2-9]{6}$'::text)),
  constraint food_stores_slug_key UNIQUE (slug),
  constraint food_stores_tax_address_length CHECK (((tax_address IS NULL) OR (char_length(tax_address) <= 800))),
  constraint food_stores_tax_branch_length CHECK (((tax_branch IS NULL) OR (char_length(tax_branch) <= 120))),
  constraint food_stores_tax_id_length CHECK (((tax_id IS NULL) OR (char_length(tax_id) <= 40))),
  constraint food_stores_tax_legal_name_length CHECK (((tax_legal_name IS NULL) OR (char_length(tax_legal_name) <= 200))),
  constraint food_stores_temporary_closed_reason_length CHECK (((temporary_closed_reason IS NULL) OR (char_length(temporary_closed_reason) <= 200)))
);

create table public.food_orders(
  id uuid default gen_random_uuid() not null,
  order_number text default food_next_order_number() not null,
  store_id uuid not null,
  buyer_id uuid,
  created_by uuid,
  source text default 'app'::text not null,
  status text default 'pending_acceptance'::text not null,
  payment_status text default 'pending'::text not null,
  recipient_name text not null,
  recipient_phone text not null,
  shipping_address text not null,
  customer_note text,
  payment_slip_path text,
  payment_note text,
  subtotal numeric not null,
  delivery_fee numeric default 0 not null,
  total numeric not null,
  eta_minutes integer,
  accepted_at timestamp with time zone,
  ready_at timestamp with time zone,
  out_for_delivery_at timestamp with time zone,
  delivered_at timestamp with time zone,
  cancelled_at timestamp with time zone,
  paid_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  payment_verification_status text default 'not_started'::text not null,
  payment_provider text,
  payment_provider_code text,
  payment_transaction_ref text,
  payment_verified_at timestamp with time zone,
  payment_verification_note text,
  source_drop_id uuid,
  refund_status text default 'none'::text not null,
  refund_note text,
  refund_requested_at timestamp with time zone,
  refunded_at timestamp with time zone,
  refund_updated_by uuid,
  campaign_id uuid,
  campaign_name text,
  campaign_discount numeric default 0 not null,
  delivery_discount numeric default 0 not null,
  delivery_latitude double precision,
  delivery_longitude double precision,
  delivery_distance_km numeric,
  scheduled_for timestamp with time zone,
  receipt_legal_name text,
  receipt_tax_id text,
  receipt_tax_branch text,
  receipt_tax_address text,
  from_share_link boolean default false not null,
  stripe_checkout_session_id text,
  stripe_payment_intent_id text,
  stripe_refund_id text,
  payment_due_at timestamp with time zone default (now() + '00:10:00'::interval),
  gp_rate_bp integer,
  gp_rate_id uuid,
  gp_rule_version text,
  constraint food_orders_campaign_discount_check CHECK (((campaign_discount >= (0)::numeric) AND (campaign_discount <= subtotal))),
  constraint food_orders_customer_note_length CHECK (((customer_note IS NULL) OR (char_length(customer_note) <= 800))),
  constraint food_orders_delivery_discount_check CHECK (((delivery_discount >= (0)::numeric) AND (delivery_discount <= delivery_fee))),
  constraint food_orders_delivery_fee_check CHECK ((delivery_fee >= (0)::numeric)),
  constraint food_orders_eta_minutes_check CHECK (((eta_minutes IS NULL) OR ((eta_minutes >= 1) AND (eta_minutes <= 240)))),
  constraint food_orders_order_number_key UNIQUE (order_number),
  constraint food_orders_payment_note_length CHECK (((payment_note IS NULL) OR (char_length(payment_note) <= 800))),
  constraint food_orders_payment_status_check CHECK ((payment_status = ANY (ARRAY['pending'::text, 'submitted'::text, 'paid'::text, 'issue'::text, 'refunded'::text]))),
  constraint food_orders_payment_verification_note_length CHECK (((payment_verification_note IS NULL) OR (char_length(payment_verification_note) <= 800))),
  constraint food_orders_payment_verification_status_check CHECK ((payment_verification_status = ANY (ARRAY['not_started'::text, 'manual_review'::text, 'auto_verified'::text, 'manual_verified'::text, 'rejected'::text]))),
  constraint food_orders_pkey PRIMARY KEY (id),
  constraint food_orders_recipient_name_length CHECK (((char_length(recipient_name) >= 1) AND (char_length(recipient_name) <= 120))),
  constraint food_orders_recipient_phone_length CHECK (((char_length(recipient_phone) >= 1) AND (char_length(recipient_phone) <= 50))),
  constraint food_orders_refund_note_length CHECK (((refund_note IS NULL) OR (char_length(refund_note) <= 800))),
  constraint food_orders_refund_status_check CHECK ((refund_status = ANY (ARRAY['none'::text, 'pending'::text, 'refunded'::text, 'failed'::text]))),
  constraint food_orders_scheduled_after_created_check CHECK (((scheduled_for IS NULL) OR (scheduled_for > created_at))),
  constraint food_orders_shipping_address_length CHECK (((char_length(shipping_address) >= 1) AND (char_length(shipping_address) <= 800))),
  constraint food_orders_source_check CHECK ((source = ANY (ARRAY['app'::text, 'manual'::text, 'social'::text]))),
  constraint food_orders_status_check CHECK ((status = ANY (ARRAY['pending_acceptance'::text, 'preparing'::text, 'ready_for_delivery'::text, 'out_for_delivery'::text, 'delivered'::text, 'cancelled'::text]))),
  constraint food_orders_subtotal_check CHECK ((subtotal >= (0)::numeric)),
  constraint food_orders_total_check CHECK ((total >= (0)::numeric)),
  constraint food_orders_total_consistency CHECK ((total = (((subtotal - campaign_discount) + delivery_fee) - delivery_discount)))
);

create table public.food_order_events(
  id bigint generated by default as identity,
  order_id uuid not null,
  event_type text not null,
  from_status text,
  to_status text,
  note text,
  actor_id uuid,
  created_at timestamp with time zone default now() not null,
  constraint food_order_events_note_length CHECK (((note IS NULL) OR (char_length(note) <= 1000))),
  constraint food_order_events_pkey PRIMARY KEY (id)
);
